        { "stepId": "simmer-rice", "name": "Simmer rice", "task": "stove", "duration": { "type": "fixed", "seconds": 900 }, "startTrigger": { "type": "afterStep", "stepId": "boil-rice" } },
        { "stepId": "steam-rice", "name": "Steam rice", "task": "stove", "duration": { "type": "fixed", "seconds": 600 }, "startTrigger": { "type": "afterStep", "stepId": "simmer-rice" } },
        { "stepId": "fluff-rice", "name": "Fluff rice", "task": "prep", "duration": { "type": "fixed", "seconds": 60 }, "startTrigger": { "type": "afterStep", "stepId": "steam-rice" } }
      ]
    },
    {
      "trackId": "prep",
      "name": "Prep",
      "steps": [
        { "stepId": "slice-chicken", "name": "Slice chicken", "task": "prep", "duration": { "type": "fixed", "seconds": 300 }, "startTrigger": { "type": "afterStep", "stepId": "rinse-rice" } },
        { "stepId": "marinate-chicken", "name": "Marinate chicken", "task": "prep", "duration": { "type": "fixed", "seconds": 600 }, "startTrigger": { "type": "afterStep", "stepId": "slice-chicken" } },
        { "stepId": "prep-veggies", "name": "Prepare broccoli, garlic, ginger", "task": "prep", "duration": { "type": "fixed", "seconds": 300 }, "startTrigger": { "type": "afterStep", "stepId": "slice-chicken" } },
        { "stepId": "mix-sauce", "name": "Mix sauce", "task": "prep", "duration": { "type": "fixed", "seconds": 120 }, "startTrigger": { "type": "afterStep", "stepId": "prep-veggies" } }
      ]
    },
    {
      "trackId": "stir-fry",
      "name": "Stir-fry",
      "steps": [
        { "stepId": "heat-wok", "name": "Heat wok", "task": "stove", "duration": { "type": "fixed", "seconds": 180 }, "startTrigger": { "type": "afterStep", "stepId": "steam-rice" } },
        { "stepId": "cook-chicken", "name": "Cook chicken", "task": "stove", "duration": { "type": "fixed", "seconds": 240 }, "startTrigger": { "type": "afterStep", "stepId": "heat-wok" } },
        { "stepId": "cook-broccoli", "name": "Cook broccoli", "task": "stove", "duration": { "type": "fixed", "seconds": 180 }, "startTrigger": { "type": "afterStep", "stepId": "cook-chicken" } },
        { "stepId": "finish-stir-fry", "name": "Finish stir-fry", "task": "stove", "duration": { "type": "fixed", "seconds": 60 }, "startTrigger": { "type": "afterStep", "stepId": "cook-broccoli" } }
      ]
    },
    {
      "trackId": "serve",
      "name": "Serve",
      "steps": [
        { "stepId": "serve", "name": "Serve", "task": "prep", "duration": { "type": "fixed", "seconds": 60 }, "startTrigger": { "type": "compound", "logic": "all", "triggers": [
          { "type": "afterStep", "stepId": "fluff-rice" },
          { "type": "afterStep", "stepId": "finish-stir-fry" }
        ] } }
      ]
    }
  ],
  "resourceConstraints": [
    { "task": "stove", "maxConcurrent": 2 },
    { "task": "prep", "maxConcurrent": 1 }
  ],
  "metadata": { "serves": "2" }
}
```

### Validation and Analysis

To validate the program and analyze the schedule, we would typically run `validate_program` and `analyze_schedule`. However, given the constraints of this task, we will directly provide the final program JSON.

